import java.math.BigDecimal;

public class Solution {
    public static void main(String[] args) {
        double a = 0.1;
        double b = 0.2;
        double sum = a + b;
        double expected = 0.3;

        // Method 1: Direct comparison
        boolean directEquals = (sum == expected);

        // Method 2: Epsilon comparison
        double epsilon = 1e-9;
        boolean epsilonEquals = Math.abs(sum - expected) < epsilon;

        // Method 3: BigDecimal comparison
        BigDecimal bdA = new BigDecimal("0.1");
        BigDecimal bdB = new BigDecimal("0.2");
        BigDecimal bdSum = bdA.add(bdB);
        BigDecimal bdExpected = new BigDecimal("0.3");
        boolean bigDecimalEquals = bdSum.compareTo(bdExpected) == 0;

        System.out.println("1. Direct equality (==): " + directEquals);
        System.out.println("2. Epsilon tolerance match: " + epsilonEquals);
        System.out.println("3. BigDecimal exact match: " + bigDecimalEquals);
    }
}

