import java.math.BigInteger;

public class Solution {
    public static void main(String[] args) {
        long factLong = 1L;
        int n = 1;
        boolean overflowDetected = false;

        while (n <= 22) {
            if (!overflowDetected) {
                try {
                    factLong = Math.multiplyExact(factLong, n);
                    System.out.println(n + "! (long) = " + factLong);
                } catch (ArithmeticException e) {
                    System.out.println("Overflow detected at " + n + "! Switching to BigInteger.");
                    overflowDetected = true;
                    BigInteger factBig = BigInteger.valueOf(factLong).multiply(BigInteger.valueOf(n));
                    System.out.println(n + "! (BigInteger) = " + factBig);
                }
            } else {
                BigInteger factBig = BigInteger.valueOf(factLong);
                for (int i = 21; i <= n; i++) {
                    factBig = factBig.multiply(BigInteger.valueOf(i));
                }
                System.out.println(n + "! (BigInteger) = " + factBig);
            }
            n++;
        }
    }
}

