public class Solution {
    static class Address {
        String city;
        Address(String city) { this.city = city; }
    }

    static class Person {
        String name;
        Address address;
        Person(String name, Address address) {
            this.name = name;
            this.address = address;
        }
        Person shallowCopy() {
            return new Person(this.name, this.address);
        }
