        System.out.println("Original City: " + original.address.city);
        System.out.println("Shallow Copy City (shared reference): " + shallow.address.city);
        System.out.println("Deep Copy City (isolated reference): " + deep.address.city);
    }
}

import java.util.Arrays;
import java.util.List;

public class Solution {
    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(10, 20, null, 40, null, 50);
        int safeSum = 0;
        int nullCount = 0;

        for (Integer num : numbers) {
            try {
                // If num is null, autoboxed unboxing to int throws NPE
                if (num == null) {
                    throw new NullPointerException("Encountered null in list");
                }
                safeSum += num; // Unboxing occurs safely here
            } catch (NullPointerException e) {
                nullCount++;
            }
        }

        System.out.println("Elements processed: " + numbers.size());
        System.out.println("Null elements skipped: " + nullCount);
        System.out.println("Calculated sum: " + safeSum);
    }
}

public class Solution {
    public static String manualToBinary(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 31; i >= 0; i--) {
            int bit = (n >>> i) & 1;
            sb.append(bit);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int number = -42;
        System.out.println("Decimal: " + number);
        System.out.println("Library Binary: " + Integer.toBinaryString(number));
        System.out.println("Library Octal:  " + Integer.toOctalString(number));
        System.out.println("Library Hex:    " + Integer.toHexString(number).toUpperCase());
        System.out.println("Manual Binary:  " + manualToBinary(number));
    }
}

public class Solution {
    public static String encrypt(String text, int shift) {
        StringBuilder result = new StringBuilder();
        for (char ch : text.toCharArray()) {
            if (ch >= 'A' && ch <= 'Z') {
                char c = (char) (((ch - 'A' + shift) % 26) + 'A');
                result.append(c);
            } else if (ch >= 'a' && ch <= 'z') {
                char c = (char) (((ch - 'a' + shift) % 26) + 'a');
                result.append(c);
            } else {
                result.append(ch);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        String original = "Hello, World!";
        int shift = 3;
        String encrypted = encrypt(original, shift);
        System.out.println("Original:  " + original);
        System.out.println("Encrypted: " + encrypted);
    }
}

