public class Solution {
    static class FixedPoint {
        private static final long SCALE = 10000L;

        public static long fromDouble(double val) {
            return Math.round(val * SCALE);
        }

        public static double toDouble(long raw) {
            return (double) raw / SCALE;
        }

        public static long add(long a, long b) {
            return a + b;
        }

        public static long subtract(long a, long b) {
            return a - b;
        }

        public static long multiply(long a, long b) {
            return (a * b) / SCALE;
        }
    }

    public static void main(String[] args) {
        long val1 = FixedPoint.fromDouble(12.5000);
        long val2 = FixedPoint.fromDouble(2.2500);

        long sum = FixedPoint.add(val1, val2);
        long diff = FixedPoint.subtract(val1, val2);
        long product = FixedPoint.multiply(val1, val2);

        System.out.printf("Val1: %.4f, Val2: %.4f%n", FixedPoint.toDouble(val1), FixedPoint.toDouble(val2));
        System.out.printf("Sum: %.4f%n", FixedPoint.toDouble(sum));
        System.out.printf("Difference: %.4f%n", FixedPoint.toDouble(diff));
        System.out.printf("Product: %.4f%n", FixedPoint.toDouble(product));
    }
}

public class Solution {
    public static long toUnsignedLong(int val) {
        return val & 0xFFFFFFFFL;
    }

    public static int unsignedDivide(int dividend, int divisor) {
        long uDividend = toUnsignedLong(dividend);
        long uDivisor = toUnsignedLong(divisor);
        return (int) (uDividend / uDivisor);
    }

    public static int unsignedCompare(int a, int b) {
        long uA = toUnsignedLong(a);
        long uB = toUnsignedLong(b);
        return Long.compare(uA, uB);
    }

    public static void main(String[] args) {
        int a = -1;  // Unsigned value is 4294967295
        int b = 2;   // Unsigned value is 2

        int divResult = unsignedDivide(a, b);
        int compResult = unsignedCompare(a, b);

        System.out.println("a = -1 (Unsigned: " + toUnsignedLong(a) + ")");
        System.out.println("b =  2 (Unsigned: " + toUnsignedLong(b) + ")");
        System.out.println("Unsigned Division (a / b): " + toUnsignedLong(divResult));
        System.out.println("Unsigned Comparison (a vs b): " + compResult);
    }
}

public class Solution {
    public static float simulateFloatAddition(float f1, float f2) {
        int b1 = Float.floatToIntBits(f1);
        int b2 = Float.floatToIntBits(f2);

        int exp1 = (b1 >>> 23) & 0xFF;
        int exp2 = (b2 >>> 23) & 0xFF;
        int mant1 = (b1 & 0x7FFFFF) | 0x800000;
        int mant2 = (b2 & 0x7FFFFF) | 0x800000;

        // Align exponents
        int expDiff = exp1 - exp2;
        if (expDiff > 0) {
            mant2 >>>= expDiff;
        } else if (expDiff < 0) {
            mant1 >>>= -expDiff;
            exp1 = exp2;
        }

        int mantSum = mant1 + mant2;
        int finalExp = exp1;

        // Normalize result if overflow occurred into bit 24
        if ((mantSum & 0x1000000) != 0) {
            mantSum >>>= 1;
            finalExp++;
        }

        int resultBits = ((finalExp & 0xFF) << 23) | (mantSum & 0x7FFFFF);
        return Float.intBitsToFloat(resultBits);
    }

    public static void main(String[] args) {
        float a = 1.5f;
        float b = 2.25f;
        float simulated = simulateFloatAddition(a, b);
        float standard = a + b;

        System.out.println("Input A: " + a + ", Input B: " + b);
        System.out.println("Simulated IEEE 754 Addition: " + simulated);
        System.out.println("Standard Hardware Addition:  " + standard);
    }
}

public class Solution {
    public static void main(String[] args) {
        int size = 1_000_000;

        // Primitive array: contiguous 4-byte ints
        long primitiveBytes = (long) size * Integer.BYTES + 16; // elements + header

        // Wrapper array: 4-byte reference per element + 16 bytes per Integer object (with Compressed OOPs)
        long referenceArrayBytes = (long) size * 4 + 16;
        long objectInstancesBytes = (long) size * 16;
        long totalWrapperBytes = referenceArrayBytes + objectInstancesBytes;

        System.out.println("Array size: " + size + " elements");
        System.out.printf("Primitive int[] memory:     ~%.2f MB%n", primitiveBytes / (1024.0 * 1024.0));
        System.out.printf("Wrapper Integer[] memory:   ~%.2f MB%n", totalWrapperBytes / (1024.0 * 1024.0));
        System.out.printf("Memory overhead factor:     ~%.1fx more memory%n", (double) totalWrapperBytes / primitiveBytes);
    }
}

public class Solution {
    static final class Money {
        private final long cents;
        private final String currency;

        public Money(long cents, String currency) {
            this.cents = cents;
            this.currency = currency;
        }

        public static Money of(double dollars, String currency) {
            return new Money(Math.round(dollars * 100), currency);
        }

        public Money add(Money other) {
            if (!this.currency.equals(other.currency)) {
                throw new IllegalArgumentException("Currency mismatch");
            }
            return new Money(Math.addExact(this.cents, other.cents), this.currency);
        }

        public Money multiply(double factor) {
            return new Money(Math.round(this.cents * factor), this.currency);
        }

        public String toString() {
            return String.format("%s %.2f", currency, cents / 100.0);
        }
    }

    public static void main(String[] args) {
        Money price = Money.of(19.99, "USD");
        Money tax = price.multiply(0.08); // 8% sales tax
        Money total = price.add(tax);

        System.out.println("Subtotal: " + price);
        System.out.println("Tax:      " + tax);
        System.out.println("Total:    " + total);
    }
}
